served_result": "eligible 653/882; corr(D_A, n_on) all=-0.475 vs eligible=-0.036; eligible median D_A=0.0529, median dPPP_allowed=-0.298; corr(D_A, dPPP_allowed)=+0.020; quadrants ~161-166 each", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "among 653 eligible, corr(D_A, dPPP_allowed)=+0.020; high-D_A names (Isaiah Joe 0.168, Trey Lyles 0.157) often allow more PPP", "observed_sample_and_power": "n=653 eligible of 882", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null", "observed_failure_type": "B_powered_null"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}, {"rel": "auto_related_family", "node": "FAM:SF-PAP-014"}]}, {"id": "FAM:SF-APPS-087", "label": "Study family SF-APPS-087: Connector tangible impact: star shielding, TO, lineup lift", "score": 0.464, "reached_via": ["request matches RQC:RQC-123 (0.74); FAM:SF-APPS-087 auto_addresses_question RQC:RQC-123"], "attributes": {"observed_research_question": "Connector tangible impact: star shielding, TO, lineup lift", "auto_outcome_status": "rejected", "observed_hypothesis": "Connector presence shields stars (higher TS, lower TO) and lifts lineup ORtg beyond talent.", "observed_result": "Star dTS +0.05 pp p=0.937; dTO +0.74 pp p=0.00364 (wrong sign for shielding). Star-init TO~HasConn beta=+0.34 pp p=0.439. HasConn on-off PPP BOTH_NULL (mean -0.041 p=0.939, median +0.528 p=0.731, n=73). Frequent-conn lin [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "PPP/TS/eFG shielding null; TO rate rises with connectors. Lineup ORtg lift is a talent confound (p=0.51 after TALENT; swap p=0.565).", "observed_verdict": "null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-086"}]}, {"id": "FAM:SF-APPA-005", "label": "Study family SF-APPA-005: Defensive scheme change within game and across games (inferred labels)", "score": 0.417, "reached_via": ["FAM:SF-CHT-052 auto_related_family (limitation_precedent) FAM:SF-APPA-005"], "attributes": {"observed_research_question": "Defensive scheme change within game and across games (inferred labels)", "auto_outcome_status": "untestable", "observed_hypothesis": "Playoff defenses change scheme within games and between games, especially after the opponent ran a play type heavily.", "observed_result": "Within-game change 319/523 (61.0%); cross-game change 298/440 (67.7%); 103/104 units (99.0%) and 52/52 series show a change; transition matrices near-uniform.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Doc caveat: inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise.", "observed_sample_and_power": "523 cells; 440 pairs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}]}], "n_results": 10}

